local require = require
local register = register
local table, pairs, tostring, error = table, pairs, tostring, error
local string = string

local sys_dect_ = {
    objectType = {
        name = "sys.dect.",
        access = "readOnly",
        minEntries = 1,
        maxEntries = 1,
        parameters = {},
    }
}

register(sys_dect_)

-- sys.dects.{i}
local sys_dect_device_i_ = {
  objectType = {
    name = "sys.dect.dev.{i}.",
    access = "readOnly",
    numEntriesParameter = "DeviceNumberOfEntries",
    minEntries = 0,
    maxEntries = math.huge,
    parameters = {
      IPUI = {
        access = "readOnly",
        type = "string",
      },
      FriendlyName = {
        access = "readOnly",
        type = "string",
      },
      LocationStatus = {
        access = "readOnly",
        type = "string",
      }
    }
  }
}

-- Open connection to UBUS
local conn = mapper("ubus").connect()

-- On newer firmware (19.4+) the DECT ubus object was renamed from mmpbxbrcmdect.devices to mmpbx.dect.devices
local function getDectDevices()
  return conn:call("mmpbx.dect.devices", "list", { }) or conn:call("mmpbxbrcmdect.devices", "list", { })
end

local function entriesSysDectDevices()
    local entries = {}
    local devices = getDectDevices()
    if devices ~= nil then 
	for k,v in pairs(devices or {}) do
	    entries[#entries+1] = k
	end
    end
    return entries
end

sys_dect_device_i_.getall = function(mapping, key)
--print(key)
    local devices = getDectDevices()
--    tprint(devices)

    for k, v in pairs (devices or {}) do
        if k == key then 
            return {
                IPUI = v["ipui"],
                FriendlyName = v["userFriendlyName"],
                LocationStatus = v["locationStatus"]
            }
        end
    end
end

sys_dect_device_i_.get = {
  IPUI = function(mapping, param, key)
    local devices = getDectDevices()
    for k, v in pairs (devices or {}) do
        if k == key then 
            return v["ipui"]
        end
    end
  end,
  FriendlyName = function(mapping, param, key)
    local devices = getDectDevices()
    for k, v in pairs (devices or {}) do
        if k == key then 
            return v["userFriendlyName"]
        end
    end
  end,
  LocationStatus = function(mapping, param, key)
    local devices = getDectDevices()
    for k, v in pairs (devices or {}) do
        if k == key then 
            return v["locationStatus"]
        end
    end
  end
}

sys_dect_device_i_.entries = entriesSysDectDevices
register(sys_dect_device_i_)
